/* =========================================================================
   P de PATA — a marca.

   As imagens abaixo são o arquivo que a Carla enviou, recortado em três
   peças (símbolo, nome e trava completa) e com o fundo branco removido.
   Nada foi redesenhado: são os mesmos pixels. Ficam embutidas em base64
   porque o sistema precisa abrir com dois cliques, sem servidor — e num
   arquivo único as imagens não podem depender de uma pasta ao lado.
   Os arquivos soltos também estão em img/, para uso fora do sistema.
   ========================================================================= */
'use strict';

var MARCA = {
  nome:    'P de PATA',
  lema:    'Conectando vidas, transformando histórias.',
  pilares: [
    { txt:'Adoção',  cor:'#FD6B01' },
    { txt:'Gestão',  cor:'#0D9B87' },
    { txt:'Conexão', cor:'#5D3CB5' }
  ],
  /* cores medidas dentro do arquivo original, não escolhidas por mim */
  laranja: '#FD6B01',
  marrom:  '#422813',
  verde:   '#0D9B87',
  roxo:    '#5D3CB5',

  simbolo:  'data:image/png;base64,',
  nomeImg:  'data:image/png;base64,',
  completo: 'data:image/png;base64,',
  icone:    'data:image/png;base64,'
};

/* Só o "P" com a pata. Sobrevive em qualquer fundo, claro ou escuro. */
function logoSimbolo(altura, classe){
  return '<img class="logo-s' + (classe ? ' ' + classe : '') + '" src="' + MARCA.simbolo +
    '" alt="' + MARCA.nome + '" style="height:' + (altura||34) + 'px;width:auto" ' +
    'draggable="false">';
}
/* O nome escrito. O "PATA" é marrom, então nunca vai direto sobre fundo
   escuro: quando o fundo for escuro, use a classe .logo-placa em volta. */
function logoNome(altura){
  return '<img class="logo-n" src="' + MARCA.nomeImg + '" alt="' + MARCA.nome +
    '" style="height:' + (altura||22) + 'px;width:auto" draggable="false">';
}
/* Símbolo + nome lado a lado — a trava horizontal, para barras e cabeçalhos. */
function logoTrava(altura){
  altura = altura || 34;
  return '<span class="logo-trava">' + logoSimbolo(altura) +
    logoNome(Math.round(altura * 0.62)) + '</span>';
}
/* A marca inteira como a Carla desenhou: símbolo, nome, pilares e lema. */
function logoCompleto(largura){
  return '<img class="logo-c" src="' + MARCA.completo + '" alt="' + MARCA.nome + ' — ' +
    MARCA.lema + '" style="width:' + (largura||260) + 'px;height:auto" draggable="false">';
}
